// Evaluate supplier engagement lifecycle state and cadence window
const activeSuppliers = [
  { supplier_id: 'SUPP_NORDIC_STEEL', state: 'VALIDATED', days_since_dispatch: 4 },
  { supplier_id: 'SUPP_SILESIAN_STEEL', state: 'SURVEY_SENT', days_since_dispatch: 7 },
  { supplier_id: 'SUPP_SHENZHEN_STAMPING', state: 'REMINDER_2', days_since_dispatch: 21 },
  { supplier_id: 'SUPP_APEX_POLYMERS', state: 'APPROVED', days_since_dispatch: 12 }
];

const actions = [];
for (const s of activeSuppliers) {
  let action = 'NO_OP';
  if (s.state === 'SURVEY_SENT' && s.days_since_dispatch >= 7) {
    action = 'SEND_REMINDER_1';
  } else if (s.state === 'REMINDER_1' && s.days_since_dispatch >= 14) {
    action = 'SEND_REMINDER_2';
  } else if (s.state === 'REMINDER_2' && s.days_since_dispatch >= 21) {
    action = 'SEND_REMINDER_3';
  } else if (s.state === 'REMINDER_3' && s.days_since_dispatch >= 28) {
    action = 'ESCALATE_TO_CATEGORY_MANAGER';
  } else if (s.state === 'ESCALATED' && s.days_since_dispatch >= 35) {
    action = 'ASSIGN_NON_RESPONDER_FALLBACK';
  }

  if (action !== 'NO_OP') {
    actions.push({
      json: {
        supplier_id: s.supplier_id,
        period_id: '2025-Q4',
        current_state: s.state,
        cadence_action: action,
        days_since_dispatch: s.days_since_dispatch
      }
    });
  }
}

return actions.length > 0 ? actions : [{ json: { cadence_action: 'ALL_UP_TO_DATE' } }];

